import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { socket } from "./socket"; // e.g., from shared socket instance from your common file
import './DMPage.css';

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]); // List of users from conversations
  const [conversations, setConversations] = useState([]); // List of conversation objects
  const [selectedChat, setSelectedChat] = useState(null); // The active conversation (other user)
  const messagesEndRef = useRef(null);

  // Scroll to the latest message whenever messages update
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Setup socket listeners once currentUser is available
  useEffect(() => {
    if (currentUser?._id) {
      console.log("Registering current user with socket:", currentUser._id);
      socket.emit("register", currentUser._id);
    }

    // Listen for incoming messages
    socket.on("receiveMessage", (message) => {
      console.log("Received message:", message);
      setMessages((prev) => [...prev, message]);
    });

    // Listen for new conversation events
    socket.on("newConversation", (conversation) => {
      console.log("🆕 New conversation received:", conversation);

      // Update the conversations list (avoid duplicates)
      setConversations((prev) => {
        if (prev.some((c) => c._id === conversation._id)) return prev;
        return [...prev, conversation];
      });

      // Determine the other participant based on currentUser
      const otherParticipant = conversation.participants.find((u) => u !== currentUser._id);
      console.log("Other participant determined:", otherParticipant);

      // Add to dmList if not already present. 
      // In a real app, you would enrich this with name, image, role etc.
      setDmList((prev) => {
        if (prev.some((user) => user._id === otherParticipant)) return prev;
        const newUser = { 
          _id: otherParticipant, 
          name: "User " + otherParticipant.slice(-4), // Dummy name; replace with actual data if available
          image: "default_user_image.jpg", 
          role: currentUser.role === "client" ? "Applicant" : "Client" 
        };
        console.log("Adding new DM user to list:", newUser);
        return [...prev, newUser];
      });
    });

    return () => {
      socket.off("receiveMessage");
      socket.off("newConversation");
    };
  }, [currentUser]);

  // Send a message to the selected chat
  const handleSend = () => {
    if (newMessage.trim() && selectedChat) {
      const messageData = {
        sender: currentUser._id,
        receiver: selectedChat._id, // The active conversation user
        message: newMessage,
      };
      console.log("Emitting sendMessage event with data:", messageData);
      socket.emit("sendMessage", messageData);
      setNewMessage('');
    }
  };

  // Handle selecting a conversation from the DM list
  const handleSelectChat = (user) => {
    console.log("Selected chat with user:", user);
    setSelectedChat(user);
    // Optionally, filter or load messages related to this conversation
  };

  // For client: Accept chat functionality
  const handleAcceptChat = () => {
    console.log("Client accepting chat with user:", selectedChat);
    // Remove chats with the rest of the applicants:
    // Here we simulate by filtering the dmList to only include the selected chat.
    setDmList([selectedChat]);
    // Optionally, you might also remove other conversations from the conversations state.
    console.log("Remaining DM list after accept:", [selectedChat]);
    // Navigate to CreateTimeline.jsx
    navigate("/createTimeline");
  };

  return (
    <div className="dm-container">
      {/* Header Navigation */}
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={() => navigate("/homes")}>Home</span>
          <span onClick={() => navigate("/profile")}>Profile</span>
          <span onClick={() => navigate("/ong-proj")}>Ongoing Projects</span>
          <span onClick={() => navigate("/post")}>Post a Job</span>
          <span onClick={() => navigate("/contact")}>Contact Us</span>
          <span onClick={() => navigate("/abt")}>About</span>
        </div>
      </div>

      <div className="dm-main">
        {/* Sidebar with DM List */}
        <div className="dm-sidebar">
          <h2>Conversations</h2>
          {dmList.map((user) => (
            <div 
              key={user._id} 
              className={`active-chat ${selectedChat && selectedChat._id === user._id ? "selected" : ""}`}
              onClick={() => handleSelectChat(user)}
            >
              <div className="user-avatar">
                <img src={user.image || "default_user_image.jpg"} alt={user.name} />
              </div>
              <div className="user-info">
                <h3>{user.name}</h3>
                <p>{user.role}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Chat Window */}
        <div className="chat-window">
          {selectedChat ? (
            <>
              <div className="chat-header">
                <h3>Chat with {selectedChat.name}</h3>
                {/* Only show Accept button if current user is a client */}
                {currentUser.role === "client" && (
                  <button onClick={handleAcceptChat} className="accept-btn">
                    Accept
                  </button>
                )}
              </div>
              <div className="messages-container">
                {messages
                  .filter((msg) => 
                    (msg.sender === selectedChat._id || msg.receiver === selectedChat._id)
                  )
                  .map((msg, index) => (
                    <div 
                      key={index} 
                      className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}
                    >
                      <div className="message-content">
                        <div className="message-header">
                          <span className="sender">
                            {msg.sender === currentUser._id ? "You" : selectedChat.name}
                          </span>
                          <span className="timestamp">
                            {new Date().toLocaleTimeString()}
                          </span>
                        </div>
                        <p>{msg.message}</p>
                      </div>
                    </div>
                  ))
                }
                <div ref={messagesEndRef} />
              </div>
              {/* Message Input */}
              <div className="message-input">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type your message..."
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                />
                <button onClick={handleSend}>
                  <svg viewBox="0 0 24 24" width="24" height="24">
                    <path fill="currentColor" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
                  </svg>
                </button>
              </div>
            </>
          ) : (
            <div className="empty-chat">
              <p>Select a conversation to start chatting.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DMPage;
